    static final JsonMapperHolder JSON=new JsonMapperHolder();
    static final HttpClient HTTP=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(3)).build();
    static final List<Map<String,Object>> CASES=new ArrayList<>(), REQUESTS=new CopyOnWriteArrayList<>(), EVENTS=new CopyOnWriteArrayList<>();
    static final List<Mail> MAIL=new CopyOnWriteArrayList<>();
    static final Set<String> FAIL_MAIL=ConcurrentHashMap.newKeySet();
    static final List<Server> SERVERS=new CopyOnWriteArrayList<>();
    static final AtomicInteger REQUEST_SEQUENCE=new AtomicInteger();static volatile String activeCase="startup";
    static Path root,out;static String jwt,ipc;static ServerSocket mailSocket;static ExecutorService mailExecutor=Executors.newVirtualThreadPerTaskExecutor();
    static Server a,b;static int seq,entityCount;static boolean provisioned,cleaned;static List<String> tables;
    static Set<String> selected=Set.of();
    static final String PASSWORD=java.util.UUID.randomUUID()+"!Aa1",NEW_PASSWORD=java.util.UUID.randomUUID()+"!Aa1";
    record Mail(String server,String email,String text){}
    record Reply(int port,int status,JsonNode json,long millis,String retry){String code(){return json.path("errorCode").asString("");}boolean ok(){return status==200&&json.path("success").asBoolean();}}
    static class JsonMapperHolder {final tools.jackson.databind.json.JsonMapper mapper=tools.jackson.databind.json.JsonMapper.builder().build();}
    static Map<String,String> protectionSettings(){var m=new LinkedHashMap<String,String>();
        for(String scope:List.of("login","verify","reset","send")){int em=scope.equals("login")?20:scope.equals("verify")?10:5;int ip=scope.equals("login")?120:scope.equals("verify")?60:20;int win=scope.equals("login")||scope.equals("verify")?60:3600;
            m.put("auth.protection."+scope+"-requests.email-max",""+em);m.put("auth.protection."+scope+"-requests.ip-max",""+ip);m.put("auth.protection."+scope+"-requests.window-seconds",""+win);}
        for(String s:List.of("login","verify")){boolean login=s.equals("login");String p="auth.protection."+s+"-failures.";m.put(p+"email-max",login?"10":"5");m.put(p+"ip-max",login?"30":"20");m.put(p+"window-seconds",login?"600":"300");m.put(p+"block-seconds",login?"60":"300");}
        m.put("auth.protection.reset-cooldown-seconds","60");m.put("auth.protection.mail-max","100");m.put("auth.protection.mail-window-seconds","3600");m.put("auth.email-verification.resend-interval-seconds","60");return m;
    }
    public static void main(String[] args)throws Exception {
        if(args.length==3)selected=Set.of(args[2].split(","));
        root=Path.of(args[0]).toRealPath();out=root.resolve("backend/tools/auth-mysql-multi-instance/results/"+LocalDate.now()+"-"+RUN);Files.createDirectories(out);
        ((ch.qos.logback.classic.Logger)org.slf4j.LoggerFactory.getLogger(org.slf4j.Logger.ROOT_LOGGER_NAME)).setLevel(ch.qos.logback.classic.Level.OFF);
        MultiSupport.database="kkiri_auth_mi_"+RUN;MultiSupport.account="kkiri_mi_"+RUN;MultiSupport.password=randomSecret();jwt=randomSecret();ipc=randomSecret();
        var startHashes=sourceHashes();boolean completed=false;
        try {
            portFree(8081);portFree(8082);
            provision();generateSchema();applySchema();startMailCapture();
            a=startServer(8081);b=startServer(8082);
            test("two-real-boot-jvms-and-shared-jwt",()->{MultiSupport.check(a.process.pid()!=b.process.pid(),"Not independent processes");String email=account("jwt");var r=login(8081,email,PASSWORD,ip());expect(r,200,"");String token=r.json.path("data").path("accessToken").asString();var me=getMe(8082,token);expect(me,200,"");return Map.of("aPid",a.process.pid(),"bPid",b.process.pid(),"crossServerJwt",true);});
            test("login-failure-and-alias-limit-shared",()->loginAlias());
            test("email-send-alias-cooldown-shared",()->sendAlias());
            test("email-verification-alias-failure-limit-shared",()->verifyFailures());
            test("same-code-concurrent-verification-on-two-servers",()->sameCode());
            test("signup-verification-token-consumed-once-across-servers",()->signupOnce());
            test("reset-alias-cooldown-and-single-token-use",()->resetAlias());
            test("first-identity-and-bucket-race",()->firstRace());
            test("email-request-quota-shared",()->emailRequestQuota());
            test("login-ip-failure-quota-shared",()->loginIp());
            test("login-check-ip-request-quota-shared",()->requestIp());
            test("verification-ip-failure-quota-shared",()->verifyIp());
            test("verification-ip-request-quota-shared",()->verifyRequestsIp());
            test("verification-send-ip-quota-shared",()->sendIp());
            test("same-email-first-send-64-requests",()->sameEmailFirstSend());
            test("different-email-first-send-independent-24",()->differentEmailFirstSend());
            test("existing-identity-cooldown-does-not-wait-on-business-mutex",()->identityReadWithoutWait());
            test("reset-ip-send-quota-shared",()->resetIp());
            test("distinct-account-limit-independence",()->independence());
            test("unknown-account-alias-response-privacy",()->unknown());
            test("cross-email-row-lock-isolation",()->unrelatedLock());
            test("cross-server-row-lock-wait-and-release",()->lockWait());
            test("http-lock-timeout-and-transaction-consistency",()->lockTimeout());
            test("forced-deadlock-involving-real-http-transaction",()->deadlock());
            test("mock-mail-failure-and-business-rollback",()->smtpRollback());
            test("limiter-1205-new-transaction-retry-recovers",()->retryTimeout());
            test("limiter-1213-new-transaction-retry-recovers",()->retryDeadlock());
            test("pool-exhaustion-error-chain-and-recovery-http",()->exhaustPool());
            test("repeat-original-132-contention-three-rounds",()->repeatContention());
            test("server-stop-restart-preserves-shared-limits",()->restartPersistence());
            test("mail-global-quota-shared-http",()->globalMailQuota());
            test("repeated-http-load-pool-return",()->poolReturn());
            MultiSupport.check(CASES.size()==(selected.isEmpty()?32:selected.size()),"Unknown/missing scenario selection");completed=true;
        } catch(Throwable t){CASES.add(Map.of("name","harness","status","INCOMPLETE","error",MultiSupport.error(t)));}
        finally {
            for(var s:SERVERS)try{s.stop();}catch(Throwable t){CASES.add(Map.of("name","server-cleanup","status","INCOMPLETE","error",MultiSupport.error(t)));}
            if(mailSocket!=null)mailSocket.close();mailExecutor.shutdownNow();
            if(provisioned&&tables!=null){try{capturePlans();}catch(Throwable t){CASES.add(Map.of("name","query-plan-capture","status","INCOMPLETE","error",MultiSupport.error(t)));}try{cleanup();cleaned=true;}catch(Throwable t){CASES.add(Map.of("name","data-cleanup","status","INCOMPLETE","error",MultiSupport.error(t)));}}
            var hashes=sourceHashes();boolean unchanged=startHashes.equals(hashes);MultiSupport.write(out.resolve("source-hashes.json"),hashes);
            MultiSupport.write(out.resolve("requests.json"),REQUESTS);MultiSupport.write(out.resolve("servers.json"),EVENTS);MultiSupport.write(out.resolve("cases.json"),CASES);
            boolean stopped=SERVERS.stream().noneMatch(s->s.process.isAlive());
            String verdict=!completed||!cleaned||!stopped||!unchanged||CASES.stream().anyMatch(x->x.get("status").equals("INCOMPLETE"))?"INSUFFICIENT":CASES.stream().anyMatch(x->x.get("status").equals("FAIL"))?"FAIL":"PASS";
            var summary=new LinkedHashMap<String,Object>();summary.put("verdict",verdict);summary.put("cases",CASES.size());summary.put("passed",CASES.stream().filter(x->x.get("status").equals("PASS")).count());summary.put("failed",CASES.stream().filter(x->x.get("status").equals("FAIL")).count());summary.put("httpRequests",REQUESTS.size());summary.put("mockMailMessages",MAIL.size());summary.put("allSpawnedProcessesStopped",stopped);summary.put("allTablesEmpty",cleaned);summary.put("productionAndPriorEvidenceUnchanged",unchanged);summary.put("database",MultiSupport.db());summary.put("account",MultiSupport.user());summary.put("realSmtpConnections",0);summary.put("bootJarSha256",args[1]);MultiSupport.write(out.resolve("summary.json"),summary);
            System.out.println("RESULT "+verdict+" evidence="+out);if(!verdict.equals("PASS"))System.exit(1);
        }
    }
    static String randomSecret(){byte[] bytes=new byte[48];new SecureRandom().nextBytes(bytes);return Base64.getEncoder().encodeToString(bytes);}
    static void portFree(int port)throws Exception {try(var socket=new ServerSocket()){socket.setReuseAddress(false);socket.bind(new InetSocketAddress("127.0.0.1",port));}}
    static String dockerRoot(String sql)throws Exception {
        var pb=new ProcessBuilder("docker","exec","-i","-e","MYSQL_PWD","kkiri-auth-mysql-test","mysql","--protocol=SOCKET","-uroot","--batch","--skip-column-names","--raw");pb.environment().put("MYSQL_PWD",System.getenv("KKIRI_MI_ROOT_PASSWORD"));
        var p=pb.start();try(var w=new OutputStreamWriter(p.getOutputStream(),StandardCharsets.UTF_8)){w.write(sql);}
        String result=new String(p.getInputStream().readAllBytes(),StandardCharsets.UTF_8);byte[] errors=p.getErrorStream().readAllBytes();MultiSupport.check(p.waitFor(20,TimeUnit.SECONDS)&&p.exitValue()==0,"Container-local provisioning query failed");return result.trim();
    }
    static void provision()throws Exception {
        MultiSupport.check(dockerRoot("SELECT CONCAT(@@server_uuid,'|',VERSION(),'|',@@hostname,'|',@@port,'|',CURRENT_USER());").equals(MultiSupport.UUID+"|8.0.46|e15a46faca0b|3306|root@localhost"),"Provisioning server identity mismatch");
        MultiSupport.check(dockerRoot("SELECT COUNT(*) FROM information_schema.schemata WHERE schema_name='"+MultiSupport.db()+"';").equals("0"),"Dedicated schema already exists");
        MultiSupport.check(dockerRoot("SELECT COUNT(*) FROM mysql.user WHERE User='"+MultiSupport.user()+"';").equals("0"),"Dedicated account already exists");
        // Wildcards in MySQL schema grants are escaped; only this literal per-run schema is authorized.
        dockerRoot("CREATE DATABASE `"+MultiSupport.db()+"` CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;\nCREATE USER '"+MultiSupport.user()+"'@'%' IDENTIFIED BY '"+MultiSupport.password+"';\nGRANT ALL PRIVILEGES ON `"+MultiSupport.db().replace("_","\\_")+"`.* TO '"+MultiSupport.user()+"'@'%';\n");
        provisioned=true;
        try(var c=MultiSupport.open()){MultiSupport.grants(c);MultiSupport.check(MultiSupport.number(c,"SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE()")==0,"New schema not empty");
            MultiSupport.write(out.resolve("environment.json"),Map.of("endpoint","127.0.0.1:3307/"+MultiSupport.db(),"account",MultiSupport.user(),"identity",MultiSupport.rows(c,"SELECT DATABASE() db,CURRENT_USER() account,USER() client,VERSION() version,@@server_uuid uuid,@@hostname hostname,@@port port,@@transaction_isolation isolation,@@session.time_zone time_zone"),"grants",MultiSupport.rows(c,"SHOW GRANTS"),"existingAuthTestDatabaseAccessed",false,"protectionSettings",protectionSettings()));}
    }
    static void generateSchema()throws Exception {
        var factory=new LocalContainerEntityManagerFactoryBean();factory.setPackagesToScan("com.kkirikkiri");factory.setJpaVendorAdapter(new HibernateJpaVendorAdapter());
        var properties=new HashMap<String,Object>();properties.put("hibernate.dialect","org.hibernate.dialect.MySQLDialect");properties.put("hibernate.boot.allow_jdbc_metadata_access",false);properties.put("hibernate.physical_naming_strategy","org.hibernate.boot.model.naming.PhysicalNamingStrategySnakeCaseImpl");
        properties.put("jakarta.persistence.schema-generation.database.action","none");properties.put("jakarta.persistence.schema-generation.scripts.action","create");properties.put("jakarta.persistence.schema-generation.scripts.create-target",out.resolve("synthetic-full-schema.sql").toString());
        factory.setJpaPropertyMap(properties);factory.afterPropertiesSet();entityCount=factory.getObject().getMetamodel().getEntities().size();factory.destroy();
    }
    static void applySchema()throws Exception {
        String sql=Files.readString(out.resolve("synthetic-full-schema.sql"));var statements=AuthMysqlMigration.split(sql);
        for(String statement:statements)MultiSupport.check(statement.matches("(?is)^(create table|create (unique )?index|alter table) .+")&&!statement.matches("(?is).*\\b(drop|truncate|grant|insert|update|delete|use)\\b.*")&&!statement.contains("kkiri_"),"Unexpected generated DDL");
        try(var c=MultiSupport.open()){MultiSupport.grants(c);for(String statement:statements)try(var s=c.createStatement()){s.execute(statement);}
            // Preserve the explicit physical ASCII contract not expressed by the Entity annotation.
            MultiSupport.exec(c,"ALTER TABLE auth_limit_bucket MODIFY bucket_key VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL");
            tables=MultiSupport.rows(c,"SELECT table_name FROM information_schema.tables WHERE table_schema=DATABASE() ORDER BY table_name").stream().map(x->x.values().iterator().next().toString()).toList();MultiSupport.check(tables.size()==entityCount,"Expected a table for every mapped entity");
            MultiSupport.write(out.resolve("initial-schema.json"),schema(c));}
    }
    static Map<String,Object> schema(Connection c)throws Exception {var m=new LinkedHashMap<String,Object>();for(String t:tables)m.put(t,MultiSupport.rows(c,"SHOW CREATE TABLE `"+t+"`"));return m;}
    static void startMailCapture()throws Exception {
        mailSocket=new ServerSocket();mailSocket.bind(new InetSocketAddress("127.0.0.1",0));mailExecutor.submit(()->{while(!mailSocket.isClosed())try{var s=mailSocket.accept();mailExecutor.submit(()->{try(s){s.setSoTimeout(3000);var input=new DataInputStream(s.getInputStream());boolean trusted=ipc.equals(input.readUTF());String server=input.readUTF(),email=input.readUTF(),text=input.readUTF();boolean accepted=trusted&&!FAIL_MAIL.contains(email);if(accepted)MAIL.add(new Mail(server,email,text));var output=new DataOutputStream(s.getOutputStream());output.writeBoolean(accepted);output.flush();}catch(Exception ignored){}});}catch(IOException ignored){break;}});
    }
    static class Server {
        final Process process;final int port;final BlockingQueue<Map<String,Object>> events=new LinkedBlockingQueue<>();final BufferedWriter input;
        Server(int port)throws Exception {this.port=port;var pb=new ProcessBuilder(Path.of(System.getProperty("java.home"),"bin","java.exe").toString(),"-Duser.timezone=Asia/Seoul","-cp",System.getProperty("java.class.path"),"MultiServer",""+port);
            var env=pb.environment();env.remove("KKIRI_MI_ROOT_PASSWORD");env.put("KKIRI_MI_DATABASE",MultiSupport.db());env.put("KKIRI_MI_USER",MultiSupport.user());env.put("KKIRI_MI_PASSWORD",MultiSupport.password);env.put("KKIRI_MI_JWT",jwt);env.put("KKIRI_MI_IPC",ipc);env.put("KKIRI_MI_MAIL_PORT",""+mailSocket.getLocalPort());
            pb.redirectErrorStream(true);process=pb.start();SERVERS.add(this);input=process.outputWriter(StandardCharsets.UTF_8);
            Thread.ofVirtual().start(()->{try(var reader=process.inputReader(StandardCharsets.UTF_8)){String line;while((line=reader.readLine())!=null)if(line.startsWith("MI_EVENT ")){Map<String,Object> e=JSON.mapper.readValue(line.substring(9),Map.class);EVENTS.add(Map.of("pid",process.pid(),"port",port,"event",e));events.add(e);}}catch(Exception ignored){}});
        }
        Map<String,Object> await(String kind,int seconds)throws Exception {long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(seconds);while(System.nanoTime()<end){var e=events.poll(1,TimeUnit.SECONDS);if(e!=null){if(e.get("kind").equals("error"))throw new IllegalStateException("Child boot failed; see servers.json");if(e.get("kind").equals(kind))return (Map<String,Object>)e.get("data");}if(!process.isAlive())throw new IllegalStateException("Child exited before event: "+kind);}throw new IllegalStateException("Child event timeout: "+kind);}
        void command(String command)throws Exception {input.write(command);input.newLine();input.flush();}
        Map<String,Object> stats()throws Exception {command("STATS");return await("pool",10);}
        void stop()throws Exception {if(!process.isAlive())return;command("STOP");if(!process.waitFor(20,TimeUnit.SECONDS)){process.destroy();if(!process.waitFor(5,TimeUnit.SECONDS))process.destroyForcibly().waitFor(5,TimeUnit.SECONDS);}MultiSupport.check(!process.isAlive(),"Child process still running");}
    }
    static Server startServer(int port)throws Exception {var s=new Server(port);s.await("ready",55);System.out.println("READY port="+port+" pid="+s.process.pid()+" database="+MultiSupport.db());return s;}
    interface Work {Map<String,Object> run()throws Exception;}
    static void test(String name,Work work)throws Exception {if(!selected.isEmpty()&&!selected.contains(name))return;long start=System.nanoTime();activeCase=name;var before=counterSnapshot();var record=new LinkedHashMap<String,Object>();record.put("name",name);
        try{record.put("result",work.run());record.put("status","PASS");System.out.println("PASS "+name);}catch(Throwable t){record.put("error",MultiSupport.error(t));record.put("status","FAIL");System.out.println("FAIL "+name);}
        var after=counterSnapshot();var changes=new TreeMap<String,Object>();for(var e:after.entrySet())if(!Objects.equals(before.get(e.getKey()),e.getValue()))changes.put(e.getKey(),e.getValue());
        record.put("dbBucketChanges",changes);var http=new TreeMap<String,Long>();for(var r:REQUESTS)if(name.equals(r.get("case")))http.merge(r.get("port")+":"+r.get("status")+":"+r.get("errorCode"),1L,Long::sum);record.put("observedHttp",http);record.put("durationMs",TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-start));CASES.add(record);MultiSupport.write(out.resolve("cases.json"),CASES);
    }
    static Map<String,Object> counterSnapshot()throws Exception {try(var c=MultiSupport.open()){var m=new TreeMap<String,Object>();for(var row:MultiSupport.rows(c,"SELECT bucket_key,request_count,failure_count,in_flight,window_started_at,generation,blocked_until FROM auth_limit_bucket"))m.put(row.get("bucket_key").toString(),row);return m;}}
    static String email(String tag){return "mi"+RUN+tag+(++seq)+"@hknu.ac.kr";}
    static String ip(){return "198.18."+(seq/200)+"."+(++seq%200+1);}
    static String alias(String e,int i){return switch(i%4){case 0->e;case 1->e.toUpperCase(Locale.ROOT).replace("@HKNU.AC.KR","@hknu.ac.kr");case 2->e.replaceFirst("i","í");default->e.replaceFirst("i","i\u0301");};}
    static String account(String tag)throws Exception {String e=email(tag);try(var c=MultiSupport.open()){MultiSupport.exec(c,"INSERT INTO user(password,school_email,email_verified,role,status,created_at,updated_at) VALUES(?,?,true,'USER','ACTIVE',NOW(),NOW())",new BCryptPasswordEncoder().encode(PASSWORD),e);}return e;}
    static String subject(String email)throws Exception {try(var c=MultiSupport.open()){return "user:"+MultiSupport.number(c,"SELECT user_id FROM user WHERE school_email=?",email);}}
    static String verificationSubject(String email)throws Exception {try(var c=MultiSupport.open()){return "verification-email:"+MultiSupport.number(c,"SELECT identity_id FROM auth_email_identity WHERE verification_email=?",email);}}
    static Map<String,Object> bucket(String scope,String subject)throws Exception {try(var c=MultiSupport.open()){return MultiSupport.rows(c,"SELECT request_count,failure_count,in_flight,generation,blocked_until FROM auth_limit_bucket WHERE bucket_key=?",MultiSupport.key(scope,subject)).getFirst();}}
    static void field(Map<String,Object> row,String key,long expected){MultiSupport.check(((Number)row.get(key)).longValue()==expected,"Counter mismatch "+key+" expected "+expected);}
    static Reply post(int port,String path,Object body,String ip)throws Exception {var req=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/auth/"+path)).timeout(Duration.ofSeconds(20)).header("Content-Type","application/json").header("X-Forwarded-For",ip).POST(HttpRequest.BodyPublishers.ofString(JSON.mapper.writeValueAsString(body))).build();return send(port,path,req);}
    static Reply getMe(int port,String token)throws Exception {return send(port,"me",HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/auth/me")).header("Authorization","Bearer "+token).GET().build());}
    static Reply send(int port,String path,HttpRequest request)throws Exception {long start=System.nanoTime();var r=HTTP.send(request,HttpResponse.BodyHandlers.ofString());var node=JSON.mapper.readTree(r.body());var reply=new Reply(port,r.statusCode(),node,TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-start),r.headers().firstValue("Retry-After").orElse(""));
        // Redact all response data: JWT, verification token and account data must never persist.
        var audit=new LinkedHashMap<String,Object>();audit.put("sequence",REQUEST_SEQUENCE.incrementAndGet());audit.put("case",activeCase);audit.put("requestId",r.headers().firstValue("X-Request-ID").orElse(""));audit.put("port",port);audit.put("path",path);audit.put("status",r.statusCode());audit.put("success",node.path("success").asBoolean());audit.put("errorCode",reply.code());audit.put("message",node.path("message").asString(""));audit.put("retryAfter",reply.retry);audit.put("millis",reply.millis);REQUESTS.add(audit);return reply;}
    static Reply login(int p,String e,String pass,String ip)throws Exception{return post(p,"login",Map.of("email",e,"password",pass),ip);}
    static Reply verify(int p,String e,String code,String ip)throws Exception{return post(p,"email-verifications/verify",Map.of("email",e,"code",code,"purpose","SIGNUP"),ip);}
    static Reply sendCode(int p,String e,String ip)throws Exception{return post(p,"email-verifications/send",Map.of("email",e,"purpose","SIGNUP"),ip);}
    static Reply reset(int p,String e,String ip)throws Exception{return post(p,"password-reset/request",Map.of("email",e),ip);}
    static Reply confirm(int p,String token)throws Exception{return post(p,"password-reset/confirm",Map.of("resetToken",token,"newPassword",NEW_PASSWORD,"newPasswordConfirm",NEW_PASSWORD),ip());}
    static void expect(Reply r,int status,String code){MultiSupport.check(r.status==status&&r.code().equals(code),"Unexpected HTTP result "+r.status+"/"+r.code()+" expected "+status+"/"+code);if(status==429)MultiSupport.check(!r.retry.isBlank()&&Long.parseLong(r.retry)>0,"Missing Retry-After");}
    interface Request {Reply run(int i,int port)throws Exception;}
    static List<Reply> concurrent(int n,Request f)throws Exception {try(var ex=Executors.newFixedThreadPool(n)){var go=new CountDownLatch(1);var fs=new ArrayList<Future<Reply>>();for(int i=0;i<n;i++){final int j=i;fs.add(ex.submit(()->{go.await();return f.run(j,j%2==0?8081:8082);}));}go.countDown();var rs=new ArrayList<Reply>();for(var future:fs)rs.add(future.get(35,TimeUnit.SECONDS));return rs;}}
    static long count(List<Reply> rs,int status,String code){return rs.stream().filter(r->r.status==status&&r.code().equals(code)).count();}
    static Map<String,Object> distribution(List<Reply> rs){var m=new TreeMap<String,Long>();for(var r:rs)m.merge(r.port+":"+r.status+":"+r.code(),1L,Long::sum);return Map.of("requests",rs.size(),"byServerStatusCode",m);}
    static List<Mail> mails(String email){return MAIL.stream().filter(m->m.email.equals(email)).toList();}
    static String code(String email){return mails(email).getLast().text.split("인증번호: ")[1].split("\n")[0];}
    static String token(String email){return mails(email).getLast().text.split("토큰: ")[1].split("\n")[0];}
    static long query(String sql,Object...args)throws Exception {try(var c=MultiSupport.open()){return MultiSupport.number(c,sql,args);}}
