    static class LockMonitor implements AutoCloseable {
        final AtomicBoolean running=new AtomicBoolean(true);final List<Object> samples=new CopyOnWriteArrayList<>();final ExecutorService executor=Executors.newSingleThreadExecutor();final Future<?> future;
        LockMonitor(){future=executor.submit(()->{while(running.get())try{String raw=dockerRoot("SELECT JSON_OBJECT('table',OBJECT_NAME,'index',INDEX_NAME,'type',LOCK_TYPE,'mode',LOCK_MODE,'status',LOCK_STATUS,'transaction',ENGINE_TRANSACTION_ID) FROM performance_schema.data_locks WHERE OBJECT_SCHEMA='"+MultiSupport.db()+"' AND OBJECT_NAME IN ('email_verification','auth_limit_bucket','auth_email_identity') AND LOCK_TYPE='RECORD' AND (LOCK_STATUS='WAITING' OR LOCK_MODE LIKE '%GAP%') LIMIT 200;");for(String line:raw.split("\\R"))if(!line.isBlank())samples.add(JSON.mapper.readValue(line,Map.class));Thread.sleep(50);}catch(Throwable t){samples.add(Map.of("observerError",MultiSupport.error(t)));break;}});}
        public void close()throws Exception {running.set(false);future.get(20,TimeUnit.SECONDS);executor.shutdown();MultiSupport.write(out.resolve("lock-samples.json"),samples);}
    }
